local config = {
  ui_story_40180001_1_dialog_content = "Que hable primero el que posea un dominio completo sobre la verdad, es decir, yo.",
  ui_story_40180001_2_dialog_content = "Sin embargo, como noble aristócrata de Lumopolis, este asunto sin duda debería ser manejado por mí.",
  ui_story_40180001_3_dialog_content = "¿De qué están discutiendo, niños? Por supuesto, algo así debería dejarse en manos de un adulto. Permíteme.",
  ui_story_40180001_4_dialog_content = "Espera, espera, espera...",
  ui_story_40180001_5_dialog_content = "Sé que dije que quería escuchar un cuento antes de dormir...",
  ui_story_40180001_6_dialog_content = "Pero no esperaba este nivel de entusiasmo...",
  ui_story_40180001_7_dialog_content = "<size=36> ¡La verdad por encima de todo! </size>",
  ui_story_40180001_8_dialog_content = "<size=40> ¡Confía en la nobleza! </size>",
  ui_story_40180001_9_dialog_content = "<size=44> ¡La antigüedad debe tener prioridad! </size>",
  ui_story_40180001_10_dialog_content = "(Que dolor de cabeza... Si hubiera sabido que esto sucedería, no me habría molestado en llamar a estos tres.)",
  ui_story_40180001_11_dialog_content = "(Las historias que me contaban antes eran muy interesantes, pero ahora se tropiezan entre sí para contarme una...)",
  ui_story_40180001_12_dialog_content = "Habla, simplón. Cuéntanos, ¿quién debería contar su historia primero?",
  ui_story_40180001_13_dialog_content = "Por supuesto, quien tenga la mejor historia debe ir primero.",
  ui_story_40180001_14_dialog_content = "Bueno, PlayerName quiere escuchar un cuento antes de dormir. Si es demasiado emocionante, no podrá dormir.",
  ui_story_40180001_15_dialog_content = "Por lo tanto, la historia más aburrida debe contarse de último, para que se duerma profundamente.",
  ui_story_40180001_16_dialog_content = "Si es así, cómo puedo negarme. Yo iré primero...",
  ui_story_40180001_17_dialog_content = "Espera, si quien tiene la mejor historia debe ir primero...",
  ui_story_40180001_18_dialog_content = "¡Claramente debería ser yo!",
  ui_story_40180001_19_dialog_content = "Una vez les conté una historia fantástica sobre un asaltante de tumbas. ¿Te acuerdas simplón?",
  ui_story_40180001_20_dialog_content = "Oh, esa... Yo...",
  ui_story_40180001_21_dialog_content = "Oye, también le conté al Navegador una historia asom. sobre el espíritu noble de mis antepasados.",
  ui_story_40180001_22_dialog_content = "Parece que ustedes, jóvenes, han aprendido bien de sus mayores. Que coincidencia... También le conté al Navegador una hist. de caza marav. curiosa.",
  ui_story_40180001_23_dialog_content = "Parece que tenemos un dilema en nuestras manos. Mejor dejemos que PlayerName decida.",
  ui_story_40180001_24_dialog_content = "PlayerName, ¿quién crees que contó la mejor historia la última vez? Esa persona debería contar la primera historia esta noche. ¿Qué piensas?",
  ui_story_40180001_25_dialog_content = "Yo... Yo...",
  ui_story_40180001_26_dialog_content = "Para ser honesto, he olvidado la mayor parte de lo que me dijeron...",
  ui_story_40180001_27_dialog_content = "¡Qué terrible desaire! ¿¡Dijiste olvidado!?",
  ui_story_40180001_28_dialog_content = "¡Por favor no se enojen!... ¿Por qué no me ayudan a recordarlo?",
  ui_story_40180001_29_dialog_content = "Déjame ver. Las tres historias eran...",
  ui_story_40180001_30_option_content = "¿Qué era Sikare Dantes?",
  ui_story_40180001_31_dialog_content = "Mi pequeño simplón, ¿realmente lo has olvidado? Una vez atrapé a un asaltante de tumbas y le pedí que me contara sus historias durante diez días y diez noches.",
  ui_story_40180001_32_dialog_content = "Una de las historias trataba de una vez que se perdió en el bosque Northland. Conoció a un niño extraño que lo sacó del bosque.",
  ui_story_40180001_33_dialog_content = "Me gustó mucho esta historia, así que a cambio, le di un preciado tesoro al asaltante de tumbas.",
  ui_story_40180001_34_dialog_content = "Y fue la verdad.",
  ui_story_40180001_35_dialog_content = "La historia de los tesoros... Sí.",
  ui_story_40180001_36_option_content = "¿Y la de Beverly?",
  ui_story_40180001_37_dialog_content = "¿Lo recuerdas, PlayerName? Me preguntaste sobre el espíritu de la nobleza.",
  ui_story_40180001_38_dialog_content = "Te hablé de la expedición de mis antepasados a Northland.",
  ui_story_40180001_39_dialog_content = "Allí derrotaron a los Eclipsites y rescataron a los aldeanos. Aunque sufrieron muchas bajas, cumplieron con sus obligaciones aristocráticas.",
  ui_story_40180001_40_dialog_content = "Sin embargo, no acep. la comida y el agua que les ofrecieron los aldeanos, lo que ejemplifica la dif. entre tu y yo.",
  ui_story_40180001_41_dialog_content = "Ahora que lo mencionas, creo recordar la historia.",
  ui_story_40180001_42_option_content = "¿Y la historia de Constantine?",
  ui_story_40180001_43_dialog_content = "Hija mía, te conté una historia sobre la caza de Eclipsites. ¿Lo recuerdas?",
  ui_story_40180001_44_dialog_content = "Mientras cazaba en el bosque de Northland, encontré una criatura extraña.",
  ui_story_40180001_45_dialog_content = "Pensé que era un Eclipsite, pero desp. de perse. durante tres horas, descubrí que era un <color=#FFB400> niño </color>.",
  ui_story_40180001_46_dialog_content = "El niño no vestía mucho y no quería irse a casa, así que le di mi <color=#FFB400> abrigo </color>.",
  ui_story_40180001_47_dialog_content = "Luego <color=#FFB400> escolté al niño fuera del bosque </color> e iba a llevarlo a casa, pero el niño desobediente se escapó.",
  ui_story_40180001_48_dialog_content = "¡El niño ni siq. se llevó el abrigo! ¡Estaba tan preocupado de que el pobre niño se resfriara!",
  ui_story_40180001_49_dialog_content = "Esa historia fue... Un poco rara.",
  ui_story_40180001_50_dialog_content = "Bueno, ahora recuerdo las tres historias.",
  ui_story_40180001_51_dialog_content = "Todas las historias fueron muy interesantes ... pero en realidad no son mat. de cuentos antes de dormir.",
  ui_story_40180001_52_dialog_content = "En cuanto a ahora... es realmente difícil para mí elegir a alguien que vaya primero.",
  ui_story_40180001_53_dialog_content = "Pero de todos modos, si debo elegir a alguien, tendrá que ser...",
  ui_story_40180001_54_dialog_content = "¡Espera!",
  ui_story_40180001_55_dialog_content = "¿Qué?",
  ui_story_40180001_56_dialog_content = "Espera, PlayerName... Puedes elegir después.",
  ui_story_40180001_57_dialog_content = "De repente me di cuenta de algo bastante aterrador...",
  ui_story_40180001_58_dialog_content = "Erm ... ¿¡Qué—!?",
  ui_story_40180001_59_dialog_content = "Sikare y Constantine contaron historias sobre... <color=#FFB400> un niño de Northland </color> ...",
  ui_story_40180001_60_dialog_content = "¿Eh? Si, es cierto...",
  ui_story_40180001_61_dialog_content = "Constantine y el asaltante de tumbas que Sikare mencionaron conocer a un niño en el bosque de Northland, y luego...",
  ui_story_40180001_X61_dialog_content = "<color=#FFB400> Salieron del bosque con el niño </color>.",
  ui_story_40180001_62_dialog_content = "¿Correcto?",
  ui_story_40180001_63_dialog_content = "Eso es.",
  ui_story_40180001_64_dialog_content = "Sí, y el niño dejó mi abrigo ...",
  ui_story_40180001_65_dialog_content = "El abrigo no es el punto aquí ... De hecho, ¡escuché la misma historia <color=#FFB400>en el pueblo donde mis antepasados fueron en su expedición </color>!",
  ui_story_40180001_66_dialog_content = "¡¿Qué?!",
  ui_story_40180001_67_dialog_content = "¿Qué? ¿También viste al niño? ¿Tenía resfriado el niño?",
  ui_story_40180001_68_dialog_content = "¡Si tenía un resfriado o no, tampoco es el punto!",
  ui_story_40180001_69_dialog_content = "Hace un tiempo, fui a Northland, al pueblo donde una vez viajaron mis antepasados.",
  ui_story_40180001_70_dialog_content = "Fui a visitar a los descen. de esos aldeanos y, en nombre de mis antepa., recibí sus regalos de comida y agua.",
  ui_story_40180001_71_dialog_content = "Luego charlamos alegremente, y los aldeanos me con. algunas historias extrañas sobre Northland, incluyendo...",
  ui_story_40180001_X71_dialog_content = "<color=#FFB400> Un cuento sobre un niño extraño en el bosque de Northland</color>.",
  ui_story_40180001_72_dialog_content = "¿Qué? ¿Recientemente? ¿Ese niño todavía va al bosque a jugar? Que niño tan travieso...",
  ui_story_40180001_73_dialog_content = "¿¡Y que pasó después!? ¡Dime!",
  ui_story_40180001_74_dialog_content = "Beverly, ¿qué te dijeron los aldeanos de Northland?",
  ui_story_40180001_75_dialog_content = "Dijeron que, el mes pasado, un aldeano se perdió en <color=#FFB400> el bosque Northland </color> y no pudo encontrar la salida.",
  ui_story_40180001_76_dialog_content = "Trató de ir en todas direcciones y no encontró nada más que un mar de árboles dondequiera que mirara.",
  ui_story_40180001_77_dialog_content = "Deambuló hasta que estuvo tan oscuro que ya no pudo ver el camino con claridad.",
  ui_story_40180001_A1_dialog_content = "Y así, el aldeano perdido se sentó en el suelo deses., creyendo que iba a morir solo en el bosque.",
  ui_story_40180001_78_dialog_content = "A decir verdad... Escuché que incluso lloró. Era un hombre fuerte, pero seguía siendo un civil común, después de todo.",
  ui_story_40180001_79_dialog_content = "¿¡Y después!? ¿Qué le pasó?",
  ui_story_40180001_80_dialog_content = "Entonces ... mientras lloraba, pensó en su niño esperándolo en casa.",
  ui_story_40180001_81_dialog_content = "Su esposa había fallecido, y su hijo no tenía a nadie más. Pensó en cómo nunca escaparía del bosque, y cómo su niño no solo no tendría madre, sino tampoco padre...",
  ui_story_40180001_A2_dialog_content = "Cayó en un pozo de desesperación y comenzó a gritar el nombre de su hijo.",
  ui_story_40180001_82_dialog_content = "Pero inespe., mientras gritaba... ¡su hijo le devolvió la llamada!",
  ui_story_40180001_83_dialog_content = "¡¿Qué?!",
  ui_story_40180001_84_dialog_content = "Conmocionado, miró hacia atrás y vio a <color=#FFB400> su hijo </color> emerger del denso bosque.",
  ui_story_40180001_85_dialog_content = "Y ... el niño llevaba un <color=#FFB400> abrigo extraño </color>, como el que lleva Constantine ahora.",
  ui_story_40180001_86_dialog_content = "¡¿Qué?!",
  ui_story_40180001_87_dialog_content = "¿¡Ese niño descartó mi abrigo y luego elaboró ​​uno que se veía exacta. igual!?",
  ui_story_40180001_88_dialog_content = "Ah... esa cosita debió haberme arrojado ese abrigo en caso de que sufriera de frío.",
  ui_story_40180001_89_dialog_content = "Debería... Debería llevarle al niño algo más adecuado... Por qué no me di cuenta... ¡Voy a pedir uno ahora mismo!",
  ui_story_40180001_90_dialog_content = "Ese niño... ¡Continúa Beverly! <color=#FFB400> ¡Ese niño </color> y el aldeano!",
  ui_story_40180001_91_dialog_content = "El aldeano... Por supuesto, se sorprendió a decir verdad.",
  ui_story_40180001_92_dialog_content = "Soltó el nombre de su niño y corrió a abrazarlo.",
  ui_story_40180001_93_dialog_content = "Un torrente de lágrimas fluyó incon. de sus ojos, derritiendo la nieve en el suelo del bosque.",
  ui_story_40180001_94_dialog_content = "El niño lo abrazó feliz, gritando \"padre\" con entus. y diciendo: \"Quería ir a casa contigo.\"",
  ui_story_40180001_95_dialog_content = "El aldeano estaba tan emocio. que ni siquiera pudo responder. Él siguió asin. con la cabeza, luego se puso de pie cuando el niño lo abrazó.",
  ui_story_40180001_96_dialog_content = "Luego, se tomaron de las manos y cami. hacia adelante, paso a paso.",
  ui_story_40180001_97_dialog_content = "En poco tiempo, <color=#FFB400> lograron salir del bosque </color>.",
  ui_story_40180001_98_dialog_content = "Una vez fuera del bosque, el aldeano conocía el cami. de reg. a casa. Estaba muy contento y fue a recoger a su niño para celebrarlo.",
  ui_story_40180001_99_dialog_content = "Pero cuando se volvió para mirarlo, de rep. descu. algo...",
  ui_story_40180001_100_dialog_content = "<anim type=Shake> <color=#FFB400> Nadie estaba a su lado. Estaba rodeado por nada más que nieve blanca... </color></anim> ¿Cómo ésta?",
  ui_story_40180001_101_dialog_content = "¡Sí! ¿Cómo lo supiste?",
  ui_story_40180001_102_dialog_content = "Porque eso es exactamente lo que dijo el asaltante de tumbas.",
  ui_story_40180001_103_dialog_content = "Un niño extraño lo sacó del bosque, y cuando se volvió para agradecer al niño, no encontró nada ni a nadie.",
  ui_story_40180001_104_dialog_content = "<anim type=Shake><color=#FFB400>Ni siquiera pudo encontrar las huellas del niño</color></anim>.",
  ui_story_40180001_105_dialog_content = "¡Es justo como pensé! ¡Tanta gente ha conocido al niño!",
  ui_story_40180001_106_dialog_content = "Ese parece ser el caso.",
  ui_story_40180001_107_dialog_content = "Espera.... ¿Podría ser histeria colectiva? ¿Una alucinación compartida o algo así?",
  ui_story_40180001_108_dialog_content = "Hace tanto frío en el bosque, es posible que uno se derrumbe después de perder el rumbo y experimente tales delirios.",
  ui_story_40180001_109_dialog_content = "Lo que dices es posible, mi pequeño simplón, sin embargo...",
  ui_story_40180001_110_dialog_content = "Constantine <color=#FFB400> conoció </color> a este mismo niño.",
  ui_story_40180001_111_dialog_content = "Es absolu. cierto... Ese niño desobediente...",
  ui_story_40180001_112_dialog_content = "Bueno, tengo mis dudas sobre si este niño es real...",
  ui_story_40180001_A3_dialog_content = "El asaltante de tumbas y los aldeanos que conociste no lo inventaron... Y no fue una alucinación que Constantine sufrió después de matar a dema. Eclipsites ...",
  ui_story_40180001_113_dialog_content = "¡Hey! ¿¡Cómo podría haber sido una alucinación!? ¡Me quité el abrigo y se lo puse al niño! ¡Toque al niño con mis propias manos!",
  ui_story_40180001_114_dialog_content = "Está bien... Pero aún tengo dudas.",
  ui_story_40180001_115_dialog_content = "Beverly, acabas de decir que el niño de la historia era el hijo del aldeano...",
  ui_story_40180001_116_dialog_content = "Oh... Si, eso es cierto.",
  ui_story_40180001_117_dialog_content = "Este punto es relativamente fácil de entender. Es normal que uno confunda a un niño con el suyo bajo el estrés de un anhelo y deses. tan fuerte.",
  ui_story_40180001_118_dialog_content = "Si lo miras de esa manera, tiene sentido...",
  ui_story_40180001_119_dialog_content = "¡Pero realmente es muy extraño!",
  ui_story_40180001_120_dialog_content = "Si mal no recuerdo, Constantine dijo que el bosque de Northland estaba <color=#FFB400>desprovisto de vida humana</color>.",
  ui_story_40180001_121_dialog_content = "¿Cómo es posible que un niño esté ahí afuera solo?",
  ui_story_40180001_122_dialog_content = "Así es, y a juzgar por los cuentos de este niño ayudando a otros, y <color=#FFB400> guiando a la salida </color>tres veces...",
  ui_story_40180001_123_dialog_content = "¿Tres veces? ¿No fue solo dos veces: el asaltante de tumbas y el aldeano?",
  ui_story_40180001_124_dialog_content = "En mi caso, acompañé al niño a casa.",
  ui_story_40180001_125_dialog_content = "No importa cuantas veces... Este niño debe estar muy familiarizado con los senderos del bosque.",
  ui_story_40180001_126_dialog_content = "Más familiar que el asaltante de tumbas o el aldeano.",
  ui_story_40180001_127_dialog_content = "Sí. El asaltante de tumbas que conocí <color=#FFB400> incluso dejaba marcas mientras caminaba </color>. De hecho, era un viajero muy experimentado.",
  ui_story_40180001_128_dialog_content = "Pero también terminó perdido.",
  ui_story_40180001_129_dialog_content = "El aldeano también <color=#FFB400> intentó caminar en todas direcciones </color>, pero no pudo encontrar una salida.",
  ui_story_40180001_130_dialog_content = "Entonces... No es tanto que el niño extraño estuviera muy familiarizado con los caminos del bosque...",
  ui_story_40180001_131_dialog_content = "Es más un caso de...",
  ui_story_40180001_132_option_content = "¿El niño vino de la nada para ayudar a esos viajeros perdidos?",
  ui_story_40180001_133_dialog_content = "Oye, vi a ese niño... ¡y el niño no tenía alas!",
  ui_story_40180001_134_option_content = "¿Quizá al niño le cavaron hoyos?",
  ui_story_40180001_135_dialog_content = "Oye, vi a ese niño... ¡y no había pala!",
  ui_story_40180001_136_dialog_content = "Esto es extraño... Si, muy extraño...",
  ui_story_40180001_137_dialog_content = "Sí, creo que es muy extraño...",
  ui_story_40180001_138_dialog_content = "Incluso cuando no se podía encontrar una salida, <color=#FFB400> el niño sacó a las pers. perdidas del bosque </color> ...",
  ui_story_40180001_139_dialog_content = "Y cuando los aldeanos vieron al niño, el niño realmente estaba <color=#FFB400> usando el extraño abrigo de Constantine </color>...",
  ui_story_40180001_140_dialog_content = "¿Cómo podría un niño crear una réplica perfecta de una prenda de vestir tan única en un bosque desierto y sin vida?",
  ui_story_40180001_141_dialog_content = "Exactamente... Ese niño habría tenido que hacer todo lo posible para crear dicho abrigo...",
  ui_story_40180001_142_dialog_content = "Incluso podría haberse pinchado el dedo meñique mien. cosía los botones...",
  ui_story_40180001_143_dialog_content = "<size=42> ¡Eso no es a lo que nos referimos! </size>",
  ui_story_40180001_144_dialog_content = "Los materiales, el estilo... <color=#FFB400> ¿Cómo podría un niño hacer esa ropa </color>? ¡Y ropa muy parecida a la de Constantine! ¡Ese es el tema!",
  ui_story_40180001_145_dialog_content = "Entonces, definitivamente hay algo que no está bien en este niño... ¡No! <color=#FFB400>¡Este niño es la fuente misma de todo lo que no está aquí </color>!",
  ui_story_40180001_146_dialog_content = "Ah... Beverly, ¡intenta mantener tu gracia aristocrática!",
  ui_story_40180001_147_dialog_content = "No dejes que las extrañas divaga. de este anciano te pierdan.",
  ui_story_40180001_148_dialog_content = "Lo siento. Perdí la cabeza.",
  ui_story_40180001_149_dialog_content = "De hecho, como este anciano fue el único que <color=#FFB400> contacto directamente </color> al niño, quisiera preguntarle ...",
  ui_story_40180001_150_dialog_content = "¿Qué quieres saber? Ese niño en realidad parecía bastante útil. No me sorprende que el niño sepa hacer ropa ...",
  ui_story_40180001_151_dialog_content = "No, no tiene sentido preguntarte.",
  ui_story_40180001_152_dialog_content = "¿Por qué no le preguntas a alguien más? Si son de Northland, es posible que hayan oído hablar de él...",
  ui_story_40180001_153_dialog_content = "Mi pequeño simplón, ¿conoces a alguien de Northland?",
  ui_story_40180001_154_dialog_content = "¿Han oído hablar de leyendas extrañas como esta?",
  ui_story_40180001_155_dialog_content = "Déjame pensar.",
  ui_story_40180001_156_option_content = "¿Reina Bethlehem?",
  ui_story_40180001_157_dialog_content = "Si alguien sabe de esto, será ella... Pero probablemente no tenga tiempo para escucharnos.",
  ui_story_40180001_158_option_content = "¿Y Constantine?",
  ui_story_40180001_159_dialog_content = "¿No entiendes, mi pequeño simplón? ¡Es imposible comunicarse con este tonto viejo raro, que parece perpetuamente obsesionado con los abrigos!",
  ui_story_40180001_160_dialog_content = "Ah... Bueno...",
  ui_story_40180001_161_dialog_content = "¿Qué tal si le preguntas a Louise?",
  ui_story_40180001_162_dialog_content = "Podrías considerar extraño mi pensamiento... Pero también me gustaría saber qué le pasó a ese niño.",
  ui_story_40180001_163_dialog_content = "A Louise le gusta aprender sobre todo tipo de leyendas. Ella debería saberlo.",
  ui_story_40180001_164_dialog_content = "Ok, iré a buscarla.",
  ui_story_40180001_165_dialog_content = "Entendido.",
  ui_story_40180001_166_dialog_content = "El asaltante de tumbas que conoció Sikare, el aldeano del que Beverly oyó hablar, e incluso la propia Constantine, se enc. con algo extraño en el bosque de Northland...\nQué fenómeno más peculiar...",
  ui_story_40180001_167_dialog_content = "El asaltante de tumbas y el aldeano se perdieron en el bosque. Pensaron que nunca lo lograrían, pero un niño los sacó del bosque y de repente apareció de la nada.",
  ui_story_40180001_168_dialog_content = "Constantine, por otro lado, quería acompañar al extraño niño a casa. Pero resulta que prob. él también estaba perdido, y simplemente no lo sabía...",
  ui_story_40180001_169_dialog_content = "Así que ahora todo mundo quiere saber <color=#FFB400> quién es este niño </color>, ¿cierto?",
  ui_story_40180001_170_dialog_content = "¡Oh, sí!",
  ui_story_40180001_171_dialog_content = "Les pedí a los tres que me contaran un cuento antes de dormir... porque no podía dormir.",
  ui_story_40180001_172_dialog_content = "¡Y debido a este lío, realmente no hay forma de que pueda dormir ahora!",
  ui_story_40180001_173_dialog_content = "Si no sabes la verdad sobre este niño... ¡Probablemente estaré despierto hasta el amanecer pensando en eso!",
  ui_story_40180001_174_dialog_content = "Comprendo.",
  ui_story_40180001_175_dialog_content = "Bueno, desafortunadamente... Temo que estarás despierto hasta la madrugada, entonces.",
  ui_story_40180001_176_dialog_content = "¿Qué? Te refieres a ...",
  ui_story_40180001_177_dialog_content = "Este niño... Es cierto que aparece en las <color=#FFB400> leyendas de Northland </color>.",
  ui_story_40180001_178_dialog_content = "La gente a veces se pierde en las prof. más profundas del bosque de Northland.",
  ui_story_40180001_179_dialog_content = "Ya sea un viajero bien preparado con brújula y mapa, un hábil cazador de Eclipsites o incluso la noble reina Bethlehem...",
  ui_story_40180001_180_dialog_content = "Si ingresas a ese bosque, no podrás irte.",
  ui_story_40180001_181_dialog_content = "Es porque los caminos en ese bosque cambian constantemente, como si estuvieran vivos.",
  ui_story_40180001_182_dialog_content = "¿Cambiando?",
  ui_story_40180001_183_dialog_content = "Sí. Cada minuto, cada segundo, cada momento, cada camino está cambiando.",
  ui_story_40180001_184_dialog_content = "Aquellos que se adentran en el bosque pierden el rumbo, pierden todo sentido de orientación y luego se desesperan.",
  ui_story_40180001_185_dialog_content = "¡Qué horrible!",
  ui_story_40180001_186_dialog_content = "Afortunadamente, un niño benévolo vive en ese bosque. Nadie sabe de dónde vino el niño...",
  ui_story_40180001_187_dialog_content = "Un niño encantador, extrovertido y muy amigable.",
  ui_story_40180001_188_dialog_content = "Cuando los viajeros se desesperan, aparece el niño y los caminos dejan de cambiar.",
  ui_story_40180001_189_dialog_content = "El niño toma al viajero perdido de la mano y lo saca del bosque.",
  ui_story_40180001_190_dialog_content = "El niño los lleva a ver las llanuras nevadas, el lago Espejo y la dirección a casa una vez más.",
  ui_story_40180001_191_dialog_content = "Esta es la leyenda tal como la escuché. Se llama <color=#FFB400> El hijo del bosque perdido</color>.",
  ui_story_40180001_192_dialog_content = "Y eso es.",
  ui_story_40180001_193_dialog_content = "Eso... ¿Es todo?",
  ui_story_40180001_194_dialog_content = "Exacto. Entonces, PlayerName, con respecto a tu evidente deseo de saber quién es este niño y qué pasa con ese bosque...",
  ui_story_40180001_195_dialog_content = "O cualquier pregunta nueva que pueda tener después de escuchar la leyenda, PlayerName, como...",
  ui_story_40180001_A4_dialog_content = "¿Los caminos en ese bosque realmente cambian todo el tiempo? ¿Y por qué dejan de moverse cuando aparece ese chico?",
  ui_story_40180001_196_dialog_content = "Desafortunadamente, <color=#FFB400>no tengo ninguna respuesta para ti </color>.",
  ui_story_40180001_197_dialog_content = "Las leyendas son leyendas por una razón: no es necesario explicarlas.",
  ui_story_40180001_198_dialog_content = "Ese es un buen punto... y vale la pena pensarlo.",
  ui_story_40180001_199_dialog_content = "Ciertamente tiene algo de verdad...",
  ui_story_40180001_200_dialog_content = "También siento... Puede ser visto como una advertencia.",
  ui_story_40180001_201_dialog_content = "Como noble, uno debe hacer investigaciones exhaustivas... Hasta donde pueda.",
  ui_story_40180001_202_dialog_content = "¡Ey! ¿¡Por qué están todos tan convencidos!?",
  ui_story_40180001_203_dialog_content = "Yo estoy aún más confundido... ¡y no puedo dormir!",
  ui_story_40180001_204_dialog_content = "¡Constantine! Tú también crees que es extraño, ¿verdad? Todavía hay tantos lugares extraños en el mundo, y necesitamos investigarlos con el mayor detalle posible, ¿¡verdad!?",
  ui_story_40180001_205_dialog_content = "¡Es correcto! ¡Todo esto es realmente muy extraño!",
  ui_story_40180001_206_dialog_content = "Lo sé, ¿cierto?",
  ui_story_40180001_207_dialog_content = "Si los caminos del bosque cambiaban constantemente, <color=#FFB400> ¿por qué no noté nada</color>?",
  ui_story_40180001_208_dialog_content = "¡Exacto!",
  ui_story_40180001_209_dialog_content = "Y si este niño realmente frecuenta el bosque, eso significa que el hogar del niño está en el bosque.",
  ui_story_40180001_A5_dialog_content = "Pero si el camino sigue cambiando, ¿cómo llega el niño a casa?",
  ui_story_40180001_210_dialog_content = "Em... ¡Exacto!",
  ui_story_40180001_211_dialog_content = "Y si el niño no puede llegar a casa, ¿cómo es posible que esa cosita haya hecho una copia de mi abrigo?",
  ui_story_40180001_212_dialog_content = "Em... ¡Sí!",
  ui_story_40180001_213_dialog_content = "No, no, no... Efectivamente, el abrigo que vio el aldeano era simplemente una ilusión. ¡El niño todavía debe estar temblando de frío!",
  ui_story_40180001_214_dialog_content = "¿Ah?",
  ui_story_40180001_215_dialog_content = "No hay tiempo que perder... ¡Debo ir a Northland y llevarle al niño algo que ponerse!",
  ui_story_40180001_X215_dialog_content = "¡Si sigue así, seguramente terminará enfermándose!",
  ui_story_40180001_216_dialog_content = "<size=36> Realmente no estás entendiendo esto, ¿verdad ...?</size>"
}
return config
